"""One owner workspace; real existing APIs, isolated synthetic data, no production decisions."""
import os,secrets,subprocess,json,requests,tempfile,shutil
from urllib.parse import urlsplit
from pathlib import Path
from playwright.sync_api import sync_playwright,expect
import test_owner_workflow as workflow
class UnifiedWorkspace(workflow.OwnerWorkflow):
 @classmethod
 def setUpClass(cls):
  super().setUpClass();cls.f.config.update(catalog_enabled=True);cls.f.write_config()
 def start_order(self):
  self.prepare_synthetic_owner();lead=self.lead();data=self.wpost(lead_id=lead,version=1).json();self.project_id=data['project_id'];project=self.owner.get(self.base+'/api.php?r=crm/projects/'+str(self.project_id)).json()['record'];updated=self.owner.patch(self.base+'/api.php?r=crm/projects/'+str(self.project_id),json={'version':int(project['version']),'description':'SYNTHETIC reviewed project requirements, scope and acceptance for one test page.'});self.assertEqual(updated.status_code,200,updated.text);return data['order_id']
 def session_page(self,browser):
  context=browser.new_context(viewport={'width':375,'height':812});context.add_cookies([{'name':c.name,'value':c.value,'url':self.base} for c in self.owner.cookies]);return context.new_page()
 def flow_action(self,oid,action,**data):
  flow=self.fg(oid).json()['record'];return self.fp(oid,action,version=int(flow['version']),reason='SYNTHETIC explicit owner decision',confirm=True,**data)
 def ready_brief(self,oid):
  self.assertEqual(self.flow_action(oid,'qualify').status_code,200);r=self.owner.post(self.base+'/api.php?r=crm/collab/projects/'+str(self.project_id)+'/documents',json={'request_key':secrets.token_hex(32),'kind':'specification','title':'SYNTHETIC unified brief','fields':{'title':'SYNTHETIC unified brief','requirements':'SYNTHETIC reviewed functionality with bounded project requirements.','acceptance':'SYNTHETIC exact visible acceptance criteria'},'file_ids':[]});self.assertEqual(r.status_code,200,r.text);rev=r.json()['revision'];r=self.owner.post(self.base+'/api.php?r=crm/collab/revisions/'+str(rev['id'])+'/ready',json={'request_key':secrets.token_hex(32),'version':int(rev['version'])});self.assertEqual(r.status_code,200,r.text);self.assertEqual(self.flow_action(oid,'brief',revision_id=int(rev['id'])).status_code,200);return rev
 def test_browser_qualify_brief_and_price_stay_on_single_workspace(self):
  oid=self.start_order()
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=self.session_page(browser);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto(self.base+'/order-workflow.php?order='+str(oid)+'&stage=qualify');page.get_by_role('heading',name='SYNTHETIC workflow',exact=False).first.wait_for();expect(page.locator('body')).to_have_attribute('data-workflow-stage','qualify');self.assertEqual(page.get_by_role('button',name='Запросить итоговую приёмку',exact=True).count(),0)
   form=page.locator('#flow-content details').filter(has=page.locator('summary',has_text='Квалифицировать обращение'));form.locator('textarea[name=reason]').fill('SYNTHETIC qualify within unified workspace');form.locator('input[type=checkbox]').check();form.get_by_role('button',name='Подтвердить и сохранить',exact=True).click();page.get_by_role('button',name='Продолжить: подготовить бриф',exact=True).click();expect(page.locator('body')).to_have_attribute('data-workflow-stage','brief');page.get_by_role('button',name='Создать документ',exact=True).click();modal=page.locator('#cc-modal');modal.get_by_label('Название',exact=True).fill('SYNTHETIC unified browser brief');modal.get_by_label('Требования',exact=True).fill('SYNTHETIC one page with exact bounded elements and scope.');modal.get_by_label('Критерии приёмки',exact=True).fill('SYNTHETIC visible heading and readable content.');modal.get_by_role('button',name='Сохранить черновик',exact=True).click();page.get_by_role('button',name='Открыть версию',exact=True).first.click();modal.get_by_role('button',name='Подготовить к отправке',exact=True).click();modal.get_by_role('button',name='Закрыть',exact=True).click();page.get_by_role('button',name='Обновить шаг',exact=True).click();bottom=page.locator('#workflow-next');bottom.locator('textarea[name=reason]').fill('SYNTHETIC exact brief checked');bottom.locator('input[type=checkbox]').check();bottom.get_by_role('button',name='Подтвердить бриф и перейти к расчёту',exact=True).click();expect(page.locator('body')).to_have_attribute('data-workflow-stage','price');page.get_by_role('heading',name='Ручная оценка проекта',exact=True).wait_for();self.assertEqual(urlsplit(page.url).path,'/order-workflow.php');self.assertEqual(len(page.context.pages),1);self.assertFalse(page.locator('input[name=project]').is_visible());self.assertEqual(page.get_by_text('Сначала создайте проект в CRM и заполните описание требований.',exact=False).count(),0);extra=page.get_by_role('checkbox',name='В этом заказе не планируются расходы на ИИ, хостинг, платные инструменты и внешние услуги.',exact=True);extra.check();self.assertEqual(page.locator('input[name=hosting_months]').input_value(),'0');extra.uncheck();self.assertEqual(page.locator('input[name=hosting_months]').input_value(),'');self.assertEqual(int(page.locator('input[name=project]').input_value()),self.project_id);self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(errors,[]);page.screenshot(path=os.path.join(tempfile.gettempdir(),'unified-order-price-mobile.png'),full_page=True);browser.close()
 def test_confirm_price_is_atomic_idempotent_and_preserves_only_exact_freshness(self):
  oid=self.start_order();self.ready_brief(oid);q=self.approved_price();records=self.wget('records&order='+str(oid)).json();payload={'order_id':oid,'version':int(records['flow']['version']),'order_version':int(records['context']['order_version']),'quotation_id':int(q['id']),'reason':'SYNTHETIC owner reviewed exact quote and amount','confirm':True,'request_key':secrets.token_hex(32)};url=self.base+'/order-workflow-api.php?r=confirm-price';bad={**payload,'order_version':999,'request_key':secrets.token_hex(32)};self.assertEqual(self.owner.post(url,json=bad).status_code,409);self.assertEqual(self.fg(oid).json()['record']['commercial_state'],'BRIEF_READY');r=self.owner.post(url,json=payload);self.assertEqual(r.status_code,200,r.text);self.assertEqual(self.owner.post(url,json=payload).json(),r.json());self.assertEqual(self.fg(oid).json()['record']['commercial_state'],'PRICE_APPROVED');fresh=self.get(self.owner,'pricing/quotes/'+str(q['id']));self.assertTrue(fresh.json()['record']['fresh'],fresh.text);self.f.sql("UPDATE nd_projects SET description='SYNTHETIC materially changed scope',version=version+1 WHERE id=?",params=[self.project_id]);self.assertFalse(self.get(self.owner,'pricing/quotes/'+str(q['id'])).json()['record']['fresh']);self.assertEqual(requests.post(url,json=payload).status_code,401)
 def test_workspace_routes_are_allowlisted_and_keep_private_headers(self):
  oid=self.start_order()
  for stage in ['act','answers','qualify','brief','price','proposal','details','contract','signatures','payment','access','production','acceptance','handover','support','archive','messages','files']:
   r=self.owner.get(self.base+'/order-workflow.php',params={'order':oid,'stage':stage});self.assertEqual(r.status_code,200,(stage,r.text[:100]));self.assertIn('data-workflow-stage="'+stage+'"',r.text);self.assertIn('workflow-shell.js',r.text);self.assertNotIn('<iframe',r.text);self.assertEqual(r.headers.get('X-Frame-Options'),'DENY');self.assertNotIn('mc.yandex',r.headers.get('Content-Security-Policy',''))
  for stage in ['../../private/config.php','unknown','../orders.php']:
   r=self.owner.get(self.base+'/order-workflow.php',params={'order':oid,'stage':stage});self.assertEqual(r.status_code,404)
 def test_spaceweb_public_html_layout_renders_without_repository_public_directory(self):
  with tempfile.TemporaryDirectory() as folder:
   root=Path(folder);shutil.copytree(self.f.path/'public',root/'public_html');shutil.copytree(self.f.path/'private',root/'private')
   for stage in ['act','answers','qualify','brief','price','proposal','details','contract','signatures','payment','access','production','acceptance','handover','support','archive','planning','messages','files']:
    code="$_SERVER['REQUEST_METHOD']='GET';$_SERVER['REQUEST_URI']='/order-workflow.php';$_GET=['order'=>'1','stage'=>"+json.dumps(stage)+"];require "+json.dumps(str(root/'public_html/order-workflow.php'))+";"
    r=subprocess.run([self.f.php,'-d','display_errors=0','-r',code],capture_output=True,text=True);self.assertEqual(r.returncode,0,r.stderr);self.assertIn('data-workflow-stage="'+stage+'"',r.stdout);self.assertIn('/workflow-shell.js?v=single-card-20261107',r.stdout)
 def test_browser_price_confirmation_uses_workspace_and_advances_without_native_dialog(self):
  oid=self.start_order();self.ready_brief(oid);self.approved_price();q=self.estimate()
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=self.session_page(browser);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.add_init_script("window.confirm=()=>{throw new Error('Native dialog must not be used');}");page.goto(self.base+'/order-workflow.php?order='+str(oid)+'&stage=price#quote/'+str(q['id']));page.get_by_label('Основание решения владельца',exact=True).fill('SYNTHETIC owner checked exact quote within workspace');page.get_by_role('checkbox',name='Я проверил оценки и риски.',exact=True).check();page.get_by_role('button',name='Одобрить точную цену',exact=True).click();page.get_by_role('button',name='Подтвердить',exact=True).click();bottom=page.locator('#workflow-next');bottom.get_by_role('button',name='Применить цену и перейти к предложению',exact=True).wait_for();bottom.get_by_label('Одобренный расчёт',exact=True).select_option(str(q['id']));bottom.locator('textarea[name=reason]').fill('SYNTHETIC apply this exact approved amount');bottom.locator('input[type=checkbox]').check();bottom.get_by_role('button',name='Применить цену и перейти к предложению',exact=True).click();expect(page.locator('body')).to_have_attribute('data-workflow-stage','proposal');self.assertEqual(urlsplit(page.url).path,'/order-workflow.php');self.assertEqual(self.fg(oid).json()['record']['commercial_state'],'PRICE_APPROVED');self.assertEqual(len(page.context.pages),1);self.assertEqual(errors,[]);browser.close()

 def test_owner_directory_visible_after_login_and_global_links_survive_order_context(self):
  oid=self.start_order();self.ready_brief(oid)
  with sync_playwright() as pw:
   browser=pw.chromium.launch(executable_path=os.environ.get('CHROMIUM_BIN','/usr/bin/chromium'),args=['--no-sandbox']);page=self.session_page(browser);errors=[];page.on('pageerror',lambda e:errors.append(str(e)))
   page.goto(self.base+'/studio.php');directory=page.locator('[data-owner-directory]');expect(directory).to_be_visible();self.assertTrue(directory.locator(':scope > details').evaluate('(n)=>n.open'));directory.get_by_label('Найти раздел',exact=True).fill('реквизиты');expect(directory.locator('.owner-directory-group:visible')).to_have_count(1);directory.get_by_label('Найти раздел',exact=True).fill('несуществующийраздел');expect(directory.locator('.owner-directory-empty')).to_be_visible();directory.get_by_label('Найти раздел',exact=True).fill('');directory.get_by_text('Документы и общение',exact=True).click();page.screenshot(path='/tmp/neuro-owner-navigation-start-mobile.png',full_page=True);page.set_viewport_size({'width':1280,'height':1000});page.screenshot(path='/tmp/neuro-owner-navigation-desktop.png',full_page=True);page.set_viewport_size({'width':375,'height':812});directory.locator('.owner-shortcuts').get_by_role('link',name='Реквизиты исполнителя',exact=True).click();page.get_by_role('heading',name='Настройки → Реквизиты исполнителя',exact=True).wait_for();self.assertEqual(urlsplit(page.url).path,'/contract-settings.php')
   page.goto(self.base+'/order-workflow.php?order='+str(oid)+'&stage=price');page.get_by_role('heading',name='Ручная оценка проекта',exact=True).wait_for();directory=page.locator('[data-owner-directory]');shortcut=directory.locator('.owner-shortcuts').get_by_role('link',name='Реквизиты исполнителя',exact=True);self.assertEqual(shortcut.get_attribute('href'),'/contract-settings.php');page.get_by_label('Название пакета работ',exact=True).fill('SYNTHETIC unsaved input');directory.locator(':scope > details > summary').click();directory.get_by_label('Найти раздел',exact=True).fill('почта');shortcut.click();self.assertEqual(urlsplit(page.url).path,'/order-workflow.php');expect(page.locator('#workflow-status')).to_contain_text('Сначала сохраните');page.goto(self.base+'/order-workflow.php?order='+str(oid)+'&stage=price');page.get_by_role('heading',name='Ручная оценка проекта',exact=True).wait_for();page.locator('.owner-shortcuts').get_by_role('link',name='Реквизиты исполнителя',exact=True).click();self.assertEqual(urlsplit(page.url).path,'/contract-settings.php');self.assertEqual(urlsplit(page.url).query,'');self.assertFalse(page.evaluate('document.documentElement.scrollWidth>innerWidth'));self.assertEqual(errors,[]);page.screenshot(path='/tmp/neuro-owner-navigation-mobile.png',full_page=True);browser.close()
 def test_directory_reaches_owner_screens_without_exposing_customer_workspace_or_private_urls(self):
  for path in ['/studio.php','/workspace.php','/order-workflow.php','/contract-settings.php','/client-settings.php','/prospect-owner.php','/help.php','/payment-settings.php','/publication-owner.php?kind=portfolio','/documents.php?mode=owner','/catalog-owner.php']:
   response=self.owner.get(self.base+path);self.assertEqual(response.status_code,200,(path,response.text[:100]));self.assertEqual(response.text.count('data-owner-directory aria-label='),1,path);self.assertIn('/owner-navigation.css?v=20261105',response.text)
  customer=requests.get(self.base+'/documents.php?mode=customer');self.assertNotIn('data-owner-directory',customer.text);self.assertEqual(requests.get(self.base+'/api.php?r=crm/settings').status_code,401);self.assertEqual(requests.get(self.base+'/lifecycle-api.php?mode=owner&r=contracts/settings').status_code,401)

for name in dir(workflow.OwnerWorkflow):
 if name.startswith('test_'):setattr(UnifiedWorkspace,name,None)
